                        "all": [
                            {"file_exists": "$machine/green.flag"},
                            {"no_open_issues": {"file": "$machine/bespoke_reviews.md"}},
                        ]
                    },
                    "actions": [
                        {
                            "ensure_file": {
                                "path": "$machine/launch.marker",
                                "content": "closed\n",
                            }
                        }
                    ],
                },
                {"stay": {"reason": "awaiting_custom_marker"}},
            ],
            terminal=False,
        ),
        "Closed": WorkflowState(
            name="Closed",
            node_name="ClosedNode",
            persisted_as="Sealed",
